     1→import { create } from "zustand";
     2→import { persist } from "zustand/middleware";
     3→import { createStackForLocation } from "@/navigation/location-navigation";
     4→import { createTabNavigationState, popTo as popNavigationState, pushPage as pushNavigationState } from "@/navigation/tab-navigation";
     5→import { locationToUrl, normalizeSettingsSection, urlToLocation } from "@/navigation/navigation-meta";
     6→import type {
     7→  BreadcrumbStackItem,
     8→  DesktopLocation,
     9→  PushPageOptions,
    10→  TabNavigationState,
    11→} from "@/navigation/navigation-meta";
    12→
    13→export type PageViewMode = "skill" | "page";
    14→
    15→export interface PageTab {
    16→  id: string;
    17→  pinned: boolean;
    18→  historyIndex: number;
    19→  navigationHistory: TabNavigationState[];
    20→  viewMode?: PageViewMode;
    21→}
    22→
    23→export interface ClosedTabSnapshot {
    24→  tab: PageTab;
    25→  closedAt: number;
    26→  originIndex: number;
    27→}
    28→
    29→interface TabState {
    30→  tabs: PageTab[];
    31→  activeTabId: string | null;
    32→  recentlyClosedTabs: ClosedTabSnapshot[];
    33→}
    34→
    35→interface OpenTabInput {
    36→  pinned?: boolean;
    37→  viewMode?: PageViewMode;
    38→  navigationState: TabNavigationState;
    39→}
    40→
    41→export interface TabViewModel extends PageTab {
    42→  currentState: TabNavigationState | null;
    43→  currentLocation: DesktopLocation | null;
    44→  label: string;
    45→  icon?: BreadcrumbStackItem["icon"];
    46→  descriptorId?: string;
    47→  meta?: BreadcrumbStackItem["meta"];
    48→  url: string | null;
    49→}
    50→
    51→interface TabActions {
    52→  openTab: (tab: OpenTabInput) => string;
    53→  closeTab: (tabId: string) => void;
    54→  closeOtherTabs: (tabId: string) => void;
    55→  closeTabsToRight: (tabId: string) => void;
    56→  setActiveTab: (tabId: string) => void;
    57→  pinTab: (tabId: string) => void;
    58→  unpinTab: (tabId: string) => void;
    59→  setViewMode: (tabId: string, mode: PageViewMode) => void;
    60→  moveTab: (fromIndex: number, toIndex: number) => void;
    61→  navigate: (tabId: string, url: string) => void;
    62→  navigateToLocation: (tabId: string, location: DesktopLocation, patch?: Partial<TabNavigationState>) => void;
    63→  replaceLocation: (tabId: string, next: TabNavigationState) => void;
    64→  pushLocation: (tabId: string, next: TabNavigationState) => void;
    65→  insertHistoryBeforeCurrent: (tabId: string, next: TabNavigationState) => void;
    66→  pushPage: (
    67→    tabId: string,
    68→    item: BreadcrumbStackItem,
    69→    location: DesktopLocation,
    70→    options?: PushPageOptions
    71→  ) => void;
    72→  popTo: (tabId: string, index: number) => void;
    73→  resetStack: (tabId: string, next: TabNavigationState) => void;
    74→  jumpToHistory: (tabId: string, historyIndex: number) => void;
    75→  goBack: (tabId: string) => void;
    76→  goForward: (tabId: string) => void;
    77→  canGoBack: (tabId: string) => boolean;
    78→  canGoForward: (tabId: string) => boolean;
    79→  getCurrentUrl: (tabId: string) => string | null;
    80→  getCurrentNavigationState: (tabId: string) => TabNavigationState | null;
    81→  closeAllTabs: () => void;
    82→  duplicateTab: (tabId: string) => string | null;
    83→  reopenClosedTab: () => string | null;
    84→  restoreTab: (tab: PageTab) => void;
    85→}
    86→
    87→const generateTabId = () =>
    88→  `tab-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
    89→const MAX_RECENTLY_CLOSED_TABS = 20;
    90→export const TAB_STORE_STORAGE_KEY = "viben-tab-store-v2";
    91→
    92→function findLastPinnedIndex(tabs: PageTab[]): number {
    93→  for (let index = tabs.length - 1; index >= 0; index -= 1) {
    94→    if (tabs[index].pinned) {
    95→      return index;
    96→    }
    97→  }
    98→  return -1;
    99→}
   100→
   101→function buildFallbackLocation(url: string): DesktopLocation {
   102→  if (url.startsWith("/workspace/") && url.includes("/apps")) {
   103→    const parts = url.split("/").filter(Boolean);
   104→    const workspaceId = parts[1];
   105→    if (workspaceId) {
   106→      return { kind: "workspace-apps", workspaceId };
   107→    }
   108→  }
   109→
   110→  if (url.startsWith("/documents")) {
   111→    return { kind: "documents" };
   112→  }
   113→
   114→  if (url.startsWith("/devices/pair")) {
   115→    return { kind: "device-pair" };
   116→  }
   117→
   118→  if (url.startsWith("/settings")) {
   119→    const section = url.split("/")[2];
   120→    return { kind: "settings", section: normalizeSettingsSection(section) };
   121→  }
   122→
   123→  return { kind: "documents" };
   124→}
   125→
   126→function buildStateFromUrl(url?: string): TabNavigationState {
   127→  const location = (url ? urlToLocation(url) : null) ?? buildFallbackLocation(url ?? "/documents");
   128→  return createTabNavigationState(location, createStackForLocation(location));
   129→}
   130→
   131→function isNavigationState(value: unknown): value is TabNavigationState {
   132→  if (!value || typeof value !== "object") return false;
   133→  const candidate = value as Partial<TabNavigationState>;
   134→  return Boolean(candidate.location && Array.isArray(candidate.breadcrumbStack));
   135→}
   136→
   137→function isPersistedPageTab(value: unknown): value is PageTab {
   138→  if (!value || typeof value !== "object") return false;
   139→  const candidate = value as Partial<PageTab>;
   140→  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
   141→}
   142→
   143→function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
   144→  if (!value || typeof value !== "object") return false;
   145→  const candidate = value as Partial<ClosedTabSnapshot>;
   146→  return (
   147→    isPersistedPageTab(candidate.tab) &&
   148→    typeof candidate.originIndex === "number" &&
   149→    typeof candidate.closedAt === "number"
   150→  );
   151→}
   152→
   153→function normalizeTab(tab: PageTab): PageTab {
   154→  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
   155→  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/documents")];
   156→  const historyIndex = Math.min(
   157→    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
   158→    safeHistory.length - 1
   159→  );
   160→
   161→  return {
   162→    id: tab.id,
   163→    pinned: Boolean(tab.pinned),
   164→    historyIndex,
   165→    navigationHistory: safeHistory,
   166→    viewMode: tab.viewMode,
   167→  };
   168→}
   169→
   170→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   171→  return {
   172→    tab: normalizeTab(snapshot.tab),
   173→    originIndex: snapshot.originIndex,
   174→    closedAt: snapshot.closedAt,
   175→  };
   176→}
   177→
   178→export function mergePersistedTabState(
   179→  persisted: Partial<TabState> | undefined,
   180→  current: TabState
   181→): TabState {
   182→  const tabs = (persisted?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
   183→  const tabIds = new Set(tabs.map((tab) => tab.id));
   184→  const activeTabId =
   185→    persisted?.activeTabId && tabIds.has(persisted.activeTabId)
   186→      ? persisted.activeTabId
   187→      : tabs[0]?.id ?? null;
   188→
   189→  return {
   190→    ...current,
   191→    tabs,
   192→    activeTabId,
   193→    recentlyClosedTabs: (persisted?.recentlyClosedTabs ?? [])
   194→      .filter(isPersistedSnapshot)
   195→      .map(normalizeSnapshot),
   196→  };
   197→}
   198→
   199→function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
   200→  return normalizeTab({
   201→    ...normalizeTab(tab),
   202→    ...overrides,
   203→    id: generateTabId(),
   204→  });
   205→}
   206→
   207→function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   208→  return {
   209→    tab: normalizeTab(tab),
   210→    originIndex,
   211→    closedAt: Date.now(),
   212→  };
   213→}
   214→
   215→function pushClosedSnapshots(
   216→  stack: ClosedTabSnapshot[],
   217→  snapshots: ClosedTabSnapshot[]
   218→): ClosedTabSnapshot[] {
   219→  if (snapshots.length === 0) {
   220→    return stack;
   221→  }
   222→
   223→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
   224→}
   225→
   226→function restoreClosedTabIntoTabs(
   227→  tabs: PageTab[],
   228→  snapshot: ClosedTabSnapshot
   229→): { tabs: PageTab[]; restoredTab: PageTab } {
   230→  const restoredTab = cloneTabWithNewId(snapshot.tab);
   231→  const nextTabs = [...tabs];
   232→  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
   233→  nextTabs.splice(insertIndex, 0, restoredTab);
   234→  return { tabs: nextTabs, restoredTab };
   235→}
   236→
   237→export function getTabCurrentState(tab: PageTab): TabNavigationState | null {
   238→  return tab.navigationHistory[tab.historyIndex] ?? null;
   239→}
   240→
   241→export function getTabCurrentLeaf(tab: PageTab): BreadcrumbStackItem | null {
   242→  const current = getTabCurrentState(tab);
   243→  return current?.breadcrumbStack[current.breadcrumbStack.length - 1] ?? null;
   244→}
   245→
   246→export function getTabUrl(tab: PageTab): string | null {
   247→  const current = getTabCurrentState(tab);
   248→  return current ? locationToUrl(current.location) : null;
   249→}
   250→
   251→export function getTabViewModel(tab: PageTab): TabViewModel {
   252→  const currentState = getTabCurrentState(tab);
   253→  const leaf = getTabCurrentLeaf(tab);
   254→  const url = getTabUrl(tab);
   255→
   256→  return {
   257→    ...tab,
   258→    currentState,
   259→    currentLocation: currentState?.location ?? null,
   260→    label: leaf?.label ?? currentState?.location.kind ?? "Untitled",
   261→    icon: leaf?.icon,
   262→    descriptorId: leaf?.descriptorId,
   263→    meta: leaf?.meta,
   264→    url,
   265→  };
   266→}
   267→
   268→function findHistoryEntryByLocation(
   269→  navigationHistory: TabNavigationState[],
   270→  historyIndex: number,
   271→  location: DesktopLocation
   272→): number {
   273→  const targetUrl = locationToUrl(location);
   274→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   275→    if (locationToUrl(navigationHistory[index].location) === targetUrl) {
   276→      return index;
   277→    }
   278→  }
   279→  return -1;
   280→}
   281→
   282→export const useTabStore = create<TabState & TabActions>()(
   283→  persist(
   284→    (set, get) => ({
   285→      tabs: [],
   286→      activeTabId: null,
   287→      recentlyClosedTabs: [],
   288→
   289→      openTab: (tabData) => {
   290→        const id = generateTabId();
   291→        const newTab = normalizeTab({
   292→          id,
   293→          pinned: tabData.pinned ?? false,
   294→          navigationHistory: [tabData.navigationState],
   295→          historyIndex: 0,
   296→          viewMode: tabData.viewMode,
   297→        });
   298→
   299→        set((state) => ({
   300→          tabs: [...state.tabs, newTab],
   301→          activeTabId: id,
   302→        }));
   303→
   304→        return id;
   305→      },
   306→
   307→      closeTab: (tabId) => {
   308→        set((state) => {
   309→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   310→          if (tabIndex === -1) return state;
   311→
   312→          const recentlyClosedTabs = pushClosedSnapshots(
   313→            state.recentlyClosedTabs,
   314→            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
   315→          );
   316→          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
   317→          let activeTabId = state.activeTabId;
   318→
   319→          if (state.activeTabId === tabId) {
   320→            if (tabs.length === 0) {
   321→              activeTabId = null;
   322→            } else if (tabIndex >= tabs.length) {
   323→              activeTabId = tabs[tabs.length - 1].id;
   324→            } else {
   325→              activeTabId = tabs[tabIndex].id;
   326→            }
   327→          }
   328→
   329→          return { tabs, activeTabId, recentlyClosedTabs };
   330→        });
   331→      },
   332→
   333→      closeOtherTabs: (tabId) => {
   334→        set((state) => {
   335→          const snapshots = state.tabs
   336→            .map((tab, index) => ({ tab, index }))
   337→            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
   338→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   339→
   340→          return {
   341→            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
   342→            activeTabId: tabId,
   343→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   344→          };
   345→        });
   346→      },
   347→
   348→      closeTabsToRight: (tabId) => {
   349→        set((state) => {
   350→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   351→          if (tabIndex === -1) return state;
   352→
   353→          const snapshots = state.tabs
   354→            .map((tab, index) => ({ tab, index }))
   355→            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
   356→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   357→          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
   358→          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
   359→          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
   360→            ? state.activeTabId
   361→            : tabId;
   362→
   363→          return {
   364→            tabs,
   365→            activeTabId,
   366→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   367→          };
   368→        });
   369→      },
   370→
   371→      setActiveTab: (tabId) => {
   372→        set({ activeTabId: tabId });
   373→      },
   374→
   375→      pinTab: (tabId) => {
   376→        set((state) => {
   377→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   378→          if (tabIndex === -1) return state;
   379→
   380→          const tab = state.tabs[tabIndex];
   381→          if (tab.pinned) return state;
   382→
   383→          const tabs = [...state.tabs];
   384→          tabs.splice(tabIndex, 1);
   385→
   386→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   387→          tabs.splice(insertIndex, 0, { ...tab, pinned: true });
   388→
   389→          return { tabs };
   390→        });
   391→      },
   392→
   393→      unpinTab: (tabId) => {
   394→        set((state) => {
   395→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   396→          if (tabIndex === -1) return state;
   397→
   398→          const tab = state.tabs[tabIndex];
   399→          if (!tab.pinned) return state;
   400→
   401→          const tabs = [...state.tabs];
   402→          tabs.splice(tabIndex, 1);
   403→
   404→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   405→          tabs.splice(insertIndex, 0, { ...tab, pinned: false });
   406→
   407→          return { tabs };
   408→        });
   409→      },
   410→
   411→      setViewMode: (tabId, mode) => {
   412→        set((state) => ({
   413→          tabs: state.tabs.map((tab) =>
   414→            tab.id === tabId ? { ...tab, viewMode: mode } : tab
   415→          ),
   416→        }));
   417→      },
   418→
   419→      moveTab: (fromIndex, toIndex) => {
   420→        set((state) => {
   421→          if (
   422→            fromIndex === toIndex ||
   423→            fromIndex < 0 ||
   424→            toIndex < 0 ||
   425→            fromIndex >= state.tabs.length ||
   426→            toIndex >= state.tabs.length
   427→          ) {
   428→            return state;
   429→          }
   430→
   431→          const tabs = [...state.tabs];
   432→          const [moved] = tabs.splice(fromIndex, 1);
   433→          tabs.splice(toIndex, 0, moved);
   434→          return { tabs };
   435→        });
   436→      },
   437→
   438→      navigate: (tabId, url) => {
   439→        get().pushLocation(tabId, buildStateFromUrl(url));
   440→      },
   441→
   442→      navigateToLocation: (tabId, location, patch) => {
   443→        get().pushLocation(
   444→          tabId,
   445→          createTabNavigationState(
   446→            location,
   447→            patch?.breadcrumbStack ?? createStackForLocation(location),
   448→            patch
   449→          )
   450→        );
   451→      },
   452→
   453→      replaceLocation: (tabId, next) => {
   454→        set((state) => ({
   455→          tabs: state.tabs.map((tab) => {
   456→            if (tab.id !== tabId) return tab;
   457→            const current = normalizeTab(tab);
   458→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   459→            return normalizeTab({
   460→              ...current,
   461→              navigationHistory: [...baseHistory, next],
   462→              historyIndex: baseHistory.length,
   463→            });
   464→          }),
   465→        }));
   466→      },
   467→
   468→      pushLocation: (tabId, next) => {
   469→        set((state) => ({
   470→          tabs: state.tabs.map((tab) => {
   471→            if (tab.id !== tabId) return tab;
   472→            const current = normalizeTab(tab);
   473→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex + 1);
   474→            return normalizeTab({
   475→              ...current,
   476→              navigationHistory: [...baseHistory, next],
   477→              historyIndex: baseHistory.length,
   478→            });
   479→          }),
   480→        }));
   481→      },
   482→
   483→      insertHistoryBeforeCurrent: (tabId, next) => {
   484→        set((state) => ({
   485→          tabs: state.tabs.map((tab) => {
   486→            if (tab.id !== tabId) return tab;
   487→            const current = normalizeTab(tab);
   488→            const before = current.navigationHistory.slice(0, current.historyIndex);
   489→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   490→            return normalizeTab({
   491→              ...current,
   492→              navigationHistory: [...before, next, ...fromCurrent],
   493→              historyIndex: before.length,
   494→            });
   495→          }),
   496→        }));
   497→      },
   498→
   499→      pushPage: (tabId, item, location, options) => {
   500→        const tab = get().tabs.find((entry) => entry.id === tabId);
   501→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   502→        if (!current) return;
   503→        get().pushLocation(tabId, pushNavigationState(current, item, location, options));
   504→      },
   505→
   506→      popTo: (tabId, index) => {
   507→        const tab = get().tabs.find((entry) => entry.id === tabId);
   508→        const current = tab ? normalizeTab(tab) : null;
   509→        const currentState = current ? getTabCurrentState(current) : null;
   510→        if (!current || !currentState) return;
   511→
   512→        const nextState = popNavigationState(currentState, index);
   513→        const matchIndex = findHistoryEntryByLocation(
   514→          current.navigationHistory,
   515→          current.historyIndex,
   516→          nextState.location
   517→        );
   518→
   519→        if (matchIndex >= 0) {
   520→          get().jumpToHistory(tabId, matchIndex);
   521→          return;
   522→        }
   523→
   524→        get().insertHistoryBeforeCurrent(tabId, nextState);
   525→      },
   526→
   527→      resetStack: (tabId, next) => {
   528→        get().replaceLocation(tabId, next);
   529→      },
   530→
   531→      jumpToHistory: (tabId, historyIndex) => {
   532→        set((state) => ({
   533→          tabs: state.tabs.map((tab) => {
   534→            if (tab.id !== tabId) return tab;
   535→            const current = normalizeTab(tab);
   536→            return normalizeTab({
   537→              ...current,
   538→              historyIndex,
   539→            });
   540→          }),
   541→        }));
   542→      },
   543→
   544→      goBack: (tabId) => {
   545→        set((state) => ({
   546→          tabs: state.tabs.map((tab) => {
   547→            if (tab.id !== tabId) return tab;
   548→            const current = normalizeTab(tab);
   549→            if (current.historyIndex <= 0) return current;
   550→            return {
   551→              ...current,
   552→              historyIndex: current.historyIndex - 1,
   553→            };
   554→          }),
   555→        }));
   556→      },
   557→
   558→      goForward: (tabId) => {
   559→        set((state) => ({
   560→          tabs: state.tabs.map((tab) => {
   561→            if (tab.id !== tabId) return tab;
   562→            const current = normalizeTab(tab);
   563→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   564→              return current;
   565→            }
   566→            return {
   567→              ...current,
   568→              historyIndex: current.historyIndex + 1,
   569→            };
   570→          }),
   571→        }));
   572→      },
   573→
   574→      canGoBack: (tabId) => {
   575→        const tab = get().tabs.find((item) => item.id === tabId);
   576→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   577→      },
   578→
   579→      canGoForward: (tabId) => {
   580→        const tab = get().tabs.find((item) => item.id === tabId);
   581→        if (!tab) return false;
   582→        const current = normalizeTab(tab);
   583→        return current.historyIndex < current.navigationHistory.length - 1;
   584→      },
   585→
   586→      getCurrentUrl: (tabId) => {
   587→        const tab = get().tabs.find((item) => item.id === tabId);
   588→        return tab ? getTabUrl(normalizeTab(tab)) : null;
   589→      },
   590→
   591→      getCurrentNavigationState: (tabId) => {
   592→        const tab = get().tabs.find((item) => item.id === tabId);
   593→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   594→      },
   595→
   596→      closeAllTabs: () => {
   597→        set((state) => {
   598→          const snapshots = state.tabs
   599→            .map((tab, index) => ({ tab, index }))
   600→            .filter(({ tab }) => !tab.pinned)
   601→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   602→          const tabs = state.tabs.filter((tab) => tab.pinned);
   603→          return {
   604→            tabs,
   605→            activeTabId: tabs[0]?.id ?? null,
   606→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   607→          };
   608→        });
   609→      },
   610→
   611→      duplicateTab: (tabId) => {
   612→        const state = get();
   613→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   614→        if (tabIndex === -1) return null;
   615→
   616→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   617→          pinned: false,
   618→        });
   619→
   620→        set((current) => {
   621→          const tabs = [...current.tabs];
   622→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   623→          return {
   624→            tabs,
   625→            activeTabId: duplicatedTab.id,
   626→          };
   627→        });
   628→
   629→        return duplicatedTab.id;
   630→      },
   631→
   632→      reopenClosedTab: () => {
   633→        let restoredTabId: string | null = null;
   634→
   635→        set((current) => {
   636→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   637→          if (!nextSnapshot) return current;
   638→
   639→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   640→          restoredTabId = restored.restoredTab.id;
   641→
   642→          return {
   643→            tabs: restored.tabs,
   644→            activeTabId: restored.restoredTab.id,
   645→            recentlyClosedTabs: restSnapshots,
   646→          };
   647→        });
   648→
   649→        return restoredTabId;
   650→      },
   651→
   652→      restoreTab: (tab) => {
   653→        const restoredTab = cloneTabWithNewId(tab);
   654→        set((state) => ({
   655→          tabs: [...state.tabs, restoredTab],
   656→          activeTabId: restoredTab.id,
   657→        }));
   658→      },
   659→    }),
   660→    {
   661→      name: TAB_STORE_STORAGE_KEY,
   662→      partialize: (state) => ({
   663→        tabs: state.tabs,
   664→        activeTabId: state.activeTabId,
   665→        recentlyClosedTabs: state.recentlyClosedTabs,
   666→      }),
   667→      merge: (persisted, current) => {
   668→        return {
   669→          ...current,
   670→          ...mergePersistedTabState(
   671→            persisted as Partial<TabState> | undefined,
   672→            current
   673→          ),
   674→        };
   675→      },
   676→    }
   677→  )
   678→);
   679→
   680→export const selectActiveTab = (state: TabState) =>
   681→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
   682→
   683→export const selectPinnedTabs = (state: TabState) =>
   684→  state.tabs.filter((tab) => tab.pinned);
   685→
   686→export const selectUnpinnedTabs = (state: TabState) =>
   687→  state.tabs.filter((tab) => !tab.pinned);
