   313→// ─── Lookup Helpers ──────────────────────────────────────────────────────────
   314→
   315→/** All descriptors in the DAG (roots + children) */
   316→const ALL_DESCRIPTORS: BreadcrumbItemDescriptor[] = [
   317→  ...GLOBAL_ROUTE_DESCRIPTORS,
   318→  ...WORKSPACE_SECTION_DESCRIPTORS,
   319→  ...SETTINGS_SECTION_DESCRIPTORS,
   320→];
   321→
   322→const DESCRIPTOR_BY_ID = new Map<string, BreadcrumbItemDescriptor>(
   323→  ALL_DESCRIPTORS.map((d) => [d.id, d])
   324→);
   325→
   326→
   327→export function getWorkspaceSectionDescriptor(section?: string): WorkspaceSectionDescriptor | undefined {
   328→  return WORKSPACE_SECTION_DESCRIPTORS.find((item) => item.section === section);
   329→}
   330→
   331→export function getWorkspaceSectionRoutePath(section: WorkspaceSection): string {
   332→  return getWorkspaceSectionDescriptor(section)?.routePath ?? section;
   333→}
   334→
   335→function isWorkspaceSection(value: string): value is WorkspaceSection {
   336→  return Boolean(getWorkspaceSectionDescriptor(value));
   337→}
   338→
   339→export function normalizeWorkspaceSection(value: string): WorkspaceSection {
   340→  if (value === "agents") return "agent";
   341→  if (isWorkspaceSection(value)) return value;
   342→  return "chat";
   343→}
   344→
   345→export function getSettingsSectionDescriptor(section?: string): SettingsSectionDescriptor | undefined {
   346→  return SETTINGS_SECTION_DESCRIPTORS.find((item) => item.section === section);
   347→}
   348→
   349→function isSettingsSection(value: string): value is SettingsSection {
   350→  return Boolean(getSettingsSectionDescriptor(value));
   351→}
   352→
   353→export function normalizeSettingsSection(value?: string | null): SettingsSection {
   354→  if (!value) return "general";
   355→  return isSettingsSection(value) ? value : "general";
