   358→export function getSettingsSectionLabel(section?: string): string {
   359→  const descriptor = getSettingsSectionDescriptor(section);
   360→  if (!descriptor) return i18n.t("settings.title", "Settings");
   361→  return i18n.t(descriptor.titleKey, descriptor.fallbackLabel);
